def predictor_accounting(model,input_dim,output_dim,retention):
 params=sum(p.numel() for p in model.parameters());macs=input_dim*model.encoder.out_features+model.encoder.out_features*output_dim if hasattr(model,"encoder") else params;dense=3*input_dim*output_dim;return {"parameters":params,"fp32_bytes":params*4,"fp16_bf16_bytes":params*2,"int8_bytes":params,"macs_per_token":macs,"flops_per_token":2*macs,"dense_ffn_macs":dense,"predictor_mac_fraction":macs/dense,"selected_ffn_fraction":retention,"total_theoretical_compute_fraction":retention+macs/dense,"output_size":output_dim}
